NAME = 'VulgSistine: Vulgata Sistina'
BOOK = 'Baruch'

CHAPTERS = {
    1: {
        1: 'Et haec verba libri, quae scripsit Baruch filius Neriae, filii Maasiae, filii Sedechiae, filii Sedei, filii Helchiae in Babylonia,',
        2: 'in anno quinto, in septimo die mensis, in tempore quo ceperunt Chaldaei Ierusalem, et succenderunt eam igne.',
        3: 'Et legit Baruch verba libri huius ad aures Iechoniae filii Ioakim regis Iuda, et ad aures universi populi venientis ad librum,',
        4: 'et ad aures potentium filiorum regum, et ad aures presbyterorum, et ad aures populi, a minimo usque ad maximum eorum omnium habitantium in Babylonia, ad flumen Sodi.',
        5: 'Qui audientes plorabant, et ieiunabant, et orabant in conspectu Domini.',
        6: 'Et collegerunt pecuniam secundum quod potuit uniuscuiusque manus,',
        7: 'et miserunt in Ierusalem ad Ioakim filium Helchiae filii Salon sacerdotem, et ad Sacerdotes, et ad omnem populum, qui inventi sunt cum eo in Ierusalem:',
        8: 'cum acciperet vasa templi Domini, quae ablata fuerant de templo, revocare in Terram Iuda decima die mensis Siban, vasa argentea, quae fecit Sedechias filius Iosiae rex Iuda,',
        9: 'posteaquam cepisset Nabuchodonosor rex Babylonis Iechoniam, et principes, et cunctos potentes, et populum terrae ab Ierusalem, et duxit eos vinctos in Babylonem.',
        10: 'Et dixerunt: Ecce misimus ad vos pecunias, de quibus emite holocaustomata, et thus, et facite manna, et offerte pro peccato ad aram Domini Dei nostri:',
        11: 'et orate pro vita Nabuchodonosor regis Babylonis, et pro vita Balthasar filii eius ut sint dies eorum sicut dies caeli super terram:',
        12: 'et ut det Dominus virtutem nobis, et illuminet oculos nostros ut vivamus sub umbra Nabuchodonosor regis Babylonis, et sub umbra Balthasar filii eius, et serviamus eis multis diebus, et inveniamus gratiam in conspectu eorum.',
        13: 'Et pro nobisipsis orate ad Dominum Deum nostrum: quia peccavimus Domino Deo nostro, et non est aversus furor eius a nobis usque in hunc diem.',
        14: 'Et legite librum istum, quem misimus ad vos recitari in templo Domini, in die sollemni, et in die opportuno:',
        15: 'et dicetis: Domino Deo nostro iustitia, nobis autem confusio faciei nostrae, sicut est dies haec omni Iuda, et habitantibus in Ierusalem,',
        16: 'Regibus nostris, et principibus nostris, et sacerdotibus nostris, et prophetis nostris, et patribus nostris.',
        17: 'Peccavimus ante Dominum Deum nostrum, et non credidimus, diffidentes in eum:',
        18: 'et non fuimus subiectibiles illi, et non audivimus vocem Domini Dei nostri ut ambularemus in mandatis eius, quae dedit nobis.',
        19: 'A die, qua eduxit patres nostros de Terra Aegypti usque ad diem hanc, eramus incredibiles ad Dominum Deum nostrum: et dissipati recessimus, ne audiremus vocem ipsius.',
        20: 'Et adhaeserunt nobis multa mala, et maledictiones, quae constituit Dominus Moysi servo suo: qui eduxit patres nostros de Terra Aegypti, dare nobis terram fluentem lac et mel, sicut hodierna die.',
        21: 'Et non audivimus vocem Domini Dei nostri secundum omnia verba prophetarum, quos misit ad nos et ad iudices nostros:',
        22: 'et abivimus unusquisque in sensum cordis nostri maligni, operari diis alienis, facientes mala ante oculos Domini Dei nostri.',
    },
    2: {
        1: 'Propter quod statuit Dominus Deus noster verbum suum, quod locutus est ad nos, et ad iudices nostros, qui iudicaverunt Israel, et ad reges nostros, et ad principes nostros, et ad omnem Israel, et Iuda:',
        2: 'ut adduceret Dominus super nos mala magna, quae non sunt facta sub caelo, quemadmodum facta sunt in Ierusalem, secundum quae scripta sunt in lege Moysi,',
        3: 'ut manducaret homo carnes filii sui, et carnes filiae suae.',
        4: 'Et dedit eos sub manu regum omnium, qui sunt in circuitu nostro in improperium, et in desolationem in omnibus populis, in quibus nos dispersit Dominus.',
        5: 'Et facti sumus subtus, et non supra: quia peccavimus Domino Deo nostro, non obaudiendo voci ipsius.',
        6: 'Domino Deo nostro iustitia: nobis autem, et patribus nostris confusio faciei, sicut est dies haec.',
        7: 'Quia locutus est Dominus super nos omnia mala haec, quae venerunt super nos:',
        8: 'et non sumus deprecati faciem Domini Dei nostri, ut reverteremur unusquisque nostrum a viis nostris pessimis.',
        9: 'Et vigilavit Dominus in malis, et adduxit ea super nos: quia iustus est Dominus in omnibus operibus suis, quae mandavit nobis:',
        10: 'et non audivimus vocem ipsius ut iremus in praeceptis Domini, quae dedit ante faciem nostram.',
        11: 'Et nunc Domine Deus Israel, qui eduxisti populum tuum de Terra Aegypti in manu valida, et in signis, et in prodigiis, et in virtute tua magna, et in brachio excelso, et fecisti tibi nomen sicut est dies iste:',
        12: 'peccavimus, impie egimus, inique gessimus Domine Deus noster, in omnibus iustitiis tuis.',
        13: 'Avertatur ira tua a nobis: quia derelicti sumus pauci inter gentes, ubi dispersisti nos.',
        14: 'Exaudi Domine preces nostras, et orationes nostras, et educ nos propter te: et da nobis invenire gratiam ante faciem eorum, qui nos abduxerunt:',
        15: 'ut sciat omnis terra quia tu es Dominus Deus noster, et quia nomen tuum invocatum est super Israel, et super genus ipsius.',
        16: 'Respice Domine de domo sancta tua in nos, et inclina aurem tuam, et exaudi nos.',
        17: 'Aperi oculos tuos, et vide: quia non mortui, qui sunt in inferno, quorum spiritus acceptus est a visceribus suis, dabunt honorem, et iustificationem Domino:',
        18: 'sed anima, quae tristis est super magnitudine mali, et incedit curva, et infirma, et oculi deficientes, et anima esuriens dat tibi gloriam et iustitiam Domino.',
        19: 'Quia non secundum iustitias patrum nostrorum nos fundimus preces, et petimus misericordiam ante conspectum tuum Domine Deus noster:',
        20: 'sed quia misisti iram tuam, et furorem tuum super nos, sicut locutus es in manu puerorum tuorum prophetarum, dicens:',
        21: 'Sic dicit Dominus: Inclinate humerum vestrum, et cervicem vestram, et opera facite regi Babylonis: et sedebitis in terra, quam dedi patribus vestris.',
        22: 'Quod si non feceritis, nec audieritis vocem Domini Dei vestri operari regi Babyloniae: defectionem vestram faciam de civitatibus Iuda, et a foris Ierusalem,',
        23: 'et auferam a vobis vocem iucunditatis, et vocem gaudii, et vocem sponsi, et vocem sponsae, et erit omnis terra sine vestigio ab inhabitantibus eam.',
        24: 'et non audierunt vocem tuam, ut operarentur regi Babylonis: et statuisti verba tua, quae locutus es in manibus puerorum tuorum prophetarum, ut transferrentur ossa regum nostrorum, et ossa patrum nostrorum de loco suo:',
        25: 'et ecce proiecta sunt in calore solis, et in gelu noctis: et mortui sunt in doloribus pessimis, in fame et in gladio, et in emissione.',
        26: 'Et posuisti templum, in quo invocatum est nomen tuum in ipso, sicut haec dies, propter iniquitatem domus Israel, et domus Iuda.',
        27: 'Et fecisti in nobis Domine Deus noster secundum omnem bonitatem tuam, et secundum omnem miserationem tuam illam magnam:',
        28: 'sicut locutus es in manu pueri tui Moysi in die, qua praecepisti ei scribere legem tuam coram filiis Israel,',
        29: 'dicens: Si non audieritis vocem meam, multitudo haec magna convertetur in minimam inter Gentes, quo ego eos dispergam:',
        30: 'quia scio quod me non audiet populus. Populus est enim dura cervice: et convertetur ad cor suum in terra captivitatis suae:',
        31: 'et scient quia ego sum Dominus Deus eorum, et dabo eis cor, et intelligent: aures, et audient.',
        32: 'Et laudabunt me in terra captivitatis suae, et memores erunt nominis mei.',
        33: 'Et avertent se a dorso suo duro, et a malignitatibus suis: quia reminiscentur viam patrum suorum qui peccaverunt in me.',
        34: 'Et revocabo illos in terram, quam iuravi patribus eorum Abraham, Isaac, et Iacob, et dominabuntur eius: et multiplicabo eos, et non minorabuntur.',
        35: 'Et statuam illis testamentum alterum sempiternum, ut sim illis in Deum, et ipsi erunt mihi in populum: et non movebo amplius populum meum, filios Israel a terra, quam dedi illis.',
    },
    3: {
        1: 'Et nunc Domine omnipotens, Deus Israel, anima in angustiis, et spiritus anxius clamat ad te:',
        2: 'audi Domine, et miserere, quia Deus es misericors, et miserere nostri: quia peccavimus ante te.',
        3: 'Quia tu sedes in sempiternum, et non peribimus in aevum?',
        4: 'Domine omnipotens, Deus Israel, audi nunc orationem mortuorum Israel, et filiorum ipsorum, qui peccaverunt ante te, et non audierunt vocem Domini Dei sui, et agglutinata sunt nobis mala.',
        5: 'Noli meminisse iniquitatum patrum nostrorum, sed memento manus tuae, et nominis tui in tempore isto:',
        6: 'quia tu es Dominus Deus noster, et laudabimus te Domine:',
        7: 'quia propter hoc dedisti timorem tuum in cordibus nostris, et ut invocemus nomen tuum, et laudemus te in captivitate nostra, quia convertimur ab iniquitate patrum nostrorum, qui peccaverunt ante te.',
        8: 'Et ecce nos in captivitate nostra sumus hodie, qua nos dispersisti in improperium, et in maledictum, et in peccatum, secundum omnes iniquitates patrum nostrorum, qui recesserunt a te Domine Deus noster.',
        9: 'Audi Israel mandata vitae: auribus percipe, ut scias prudentiam.',
        10: 'Quid est Israel quod in terra inimicorum es?',
        11: 'inveterasti in terra aliena, coinquinatus es cum mortuis: deputatus es cum descendentibus in infernum.',
        12: 'Dereliquisti fontem sapientiae.',
        13: 'nam si in via Dei ambulasses, habitasses utique in pace super terram.',
        14: 'Disce ubi sit prudentia, ubi sit virtus, ubi sit intellectus: ut scias simul ubi sit longiturnitas vitae et victus, ubi sit lumen oculorum, et pax.',
        15: 'Quis invenit locum eius? et quis intravit in thesauros eius?',
        16: 'Ubi sunt principes Gentium, et qui dominantur super bestias, quae sunt super terram?',
        17: 'qui in avibus caeli ludunt,',
        18: 'qui argentum thesaurizant, et aurum, in quo confidunt homines, et non est finis acquisitionis eorum? qui argentum fabricant et soliciti sunt, nec est inventio operum illorum?',
        19: 'Exterminati sunt, et ad inferos descenderunt, et alii loco eorum surrexerunt.',
        20: 'Iuvenes viderunt lumen, et habitaverunt super terram: viam autem disciplinae ignoraverunt,',
        21: 'neque intellexerunt semitas eius, neque filii eorum susceperunt eam, a facie ipsorum longe facta est.:',
        22: 'non est audita in Terra Chanaam, neque visa est in Theman.',
        23: 'Filii quoque Agar, qui exquirunt prudentiam, quae de terra est, negotiatores terrae, et Theman, et fabulatores, et exquisitores prudentiae et intelligentiae: viam autem sapientiae nescierunt, neque commemorati sunt semitas eius.',
        24: 'O Israel quam magna est domus Dei, et ingens locus possessionis eius!',
        25: 'Magnus est, et non habet finem: excelsus et immensus.',
        26: 'Ibi fuerunt gigantes nominati illi, qui ab initio fuerunt, statura magna, scientes bellum.',
        27: 'Non hos elegit Dominus, neque viam disciplinae invenerunt: propterea perierunt.',
        28: 'Et quoniam non habuerunt sapientiam, interierunt propter suam insipientiam.',
        29: 'Quis ascendit in caelum, et accepit eam, et eduxit eam de nubibus?',
        30: 'Quis transfretavit mare, et invenit illam? et attulit illam super aurum electum?',
        31: 'Non est qui possit scire vias eius, neque qui exquirat semitas eius:',
        32: 'sed qui scit universa, novit eam, et adinvenit eam prudentia sua: qui praeparavit terram in aeterno tempore, et replevit eam pecudibus, et quadrupedibus:',
        33: 'qui emittit lumen, et vadit: et vocavit illud, et obedit illi in tremore.',
        34: 'Stellae autem dederunt lumen in custodiis suis, et laetatae sunt:',
        35: 'vocatae sunt, et dixerunt: Adsumus: et luxerunt ei cum iucunditate, qui fecit illas.',
        36: 'Hic est Deus noster, et non aestimabitur alius adversus eum.',
        37: 'Hic adinvenit omnem viam disciplinae, et tradidit illam Iacob puero suo, et Israel dilecto suo.',
        38: 'Post haec in terris visus est, et cum hominibus conversatus est.',
    },
    4: {
        1: 'Hic liber mandatorum Dei, et lex, quae est in aeternum: omnes, qui tenent eam, pervenient ad vitam: qui autem dereliquerunt eam, in mortem.',
        2: 'Convertere Iacob, et apprehende eam, ambula per viam ad splendorem eius contra lumen eius.',
        3: 'Ne tradas alteri gloriam tuam, et dignitatem tuam genti alienae.',
        4: 'Beati sumus Israel: quia quae Deo placent, manifesta sunt nobis.',
        5: 'Animaequior esto populus Dei, memorabilis Israel:',
        6: 'venundati estis Gentibus non in perditionem: sed propter quod ad iracundiam provocastis Deum, traditi estis adversariis.',
        7: 'Exacerbastis enim eum, qui fecit vos, Deum aeternum, immolantes daemoniis, et non Deo.',
        8: 'Obliti enim estis Deum, qui nutrivit vos, et contristastis nutricem vestram Ierusalem.',
        9: 'Vidit enim iracundiam a Deo venientem vobis, et dixit: Audite confines Sion, adduxit enim mihi Deus luctum magnum:',
        10: 'Vidi enim captivitatem populi mei, filiorum meorum, et filiarum, quam superduxit illis aeternus.',
        11: 'Nutrivi enim illos cum iucunditate: dimisi autem illos cum fletu et luctu.',
        12: 'Nemo gaudeat super me viduam, et desolatam: a multis derelicta sum propter peccata filiorum meorum, quia declinaverunt a lege Dei.',
        13: 'Iustitias autem ipsius nescierunt, nec ambulaverunt per vias mandatorum Dei, neque per semitas veritatis eius cum iustitia ingressi sunt.',
        14: 'Veniant confines Sion, et memorentur captivitatem filiorum, et filiarum mearum, quam superduxit illis aeternus.',
        15: 'Adduxit enim super illos gentem de longinquo, gentem improbam, et alterius linguae:',
        16: 'qui non sunt reveriti senem, neque puerorum miserti sunt, et abduxerunt dilectos viduae, et a filiis unicam desolaverunt.',
        17: 'Ego autem quid possum adiuvare vos?',
        18: 'Qui enim adduxit super vos mala, ipse vos eripiet de manibus inimicorum vestrorum.',
        19: 'Ambulate filii, ambulate: ego enim derelicta sum sola.',
        20: 'Exue me stola pacis, indui autem me sacco obsecrationis, et clamabo ad Altissimum in diebus meis.',
        21: 'Animaequiores estote filii, clamate ad Dominum, et eripiet vos de manu principum inimicorum.',
        22: 'Ego enim speravi in aeternum salutem vestram: et venit mihi gaudium a sancto super misericordia, quae veniet vobis ab aeterno salutari nostro.',
        23: 'Emisi enim vos cum luctu et ploratu: reducet autem vos mihi Dominus cum gaudio et iucunditate in sempiternum.',
        24: 'Sicut enim viderunt vicinae Sion captivitatem vestram a Deo, sic videbunt et in celeritate salutem vestram a Deo, quae superveniet vobis cum honore magno, et splendore aeterno.',
        25: 'Filii patienter sustinete iram, quae supervenit vobis: persecutus est enim te inimicus tuus, sed cito videbis perditionem ipsius: et super cervices ipsius ascendes.',
        26: 'Delicati mei ambulaverunt vias asperas: ducti sunt enim ut grex direptus ab inimicis.',
        27: 'Animaequiores estote filii, et proclamate ad Dominum: erit enim memoria vestra ab eo, qui duxit vos.',
        28: 'Sicut enim fuit sensus vester ut erraretis a Deo: decies tantum iterum convertentes requiretis eum.',
        29: 'Qui enim induxit vobis mala, ipse rursum adducet vobis sempiternam iucunditatem cum salute vestra.',
        30: 'Animaequior esto Ierusalem, exhortatur enim te, qui te nominavit.',
        31: 'Nocentes peribunt, qui te vexaverunt: et qui gratulati sunt in tua ruina, punientur.',
        32: 'civitates, quibus servierunt filii tui, punientur: et quae accepit filios tuos.',
        33: 'Sicut gavisa est in tua ruina, et laetata est in casu tuo, sic contristabitur in sua desolatione.',
        34: 'Et amputabitur exultatio multitudinis eius, et gaudimonium eius erit in luctum.',
        35: 'Ignis enim superveniet ei ab aeterno in longiturnis diebus, et habitabitur a daemoniis in multitudine temporis.',
        36: 'Circumspice Ierusalem ad Orientem, et vide iucunditatem a Deo tibi venientem.',
        37: 'Ecce enim veniunt filii tui, quos dimisisti dispersos, veniunt collecti ab Oriente usque ad Occidentem, in verbo sancti gaudentes in honorem Dei.',
    },
    5: {
        1: 'Exue te Ierusalem stola luctus, et vexationis tuae: et indue te decore, et honore eius, quae a Deo tibi est sempiternae gloriae.',
        2: 'Circumdabit te Deus diploide iustitiae, et imponet mitram capiti honoris aeterni.',
        3: 'Deus enim ostendet splendorem suum in te omni, qui sub caelo est.',
        4: 'Nominabitur enim tibi nomen tuum a Deo in sempiternum: Pax iustitiae, et honor pietatis.',
        5: 'Exurge Ierusalem, et sta in excelso: et circumspice ad Orientem, et vide collectos filios tuos ab Oriente sole usque ad Occidentem, in verbo sancti gaudentes Dei memoria.',
        6: 'Exierunt enim abs te pedibus ducti ab inimicis: adducet autem illos Dominus ad te portatos in honorem sicut filios regni.',
        7: 'Constituit enim Deus humiliare omnem montem excelsum, et rupes perennes, et convalles replere in aequalitatem terrae: ut ambulet Israel diligenter in honorem Dei.',
        8: 'Obumbraverunt autem et silvae, et omne lignum suavitatis Israel ex mandato Dei.',
        9: 'Adducet enim Deus Israel cum iucunditate in lumine maiestatis suae, cum misericordia, et iustitia, quae est ex ipso.',
    },
    6: {
        1: 'Exemplar epistolae, quam misit Ieremias ad abducendos captivos in Babyloniam a rege Babyloniorum, ut annunciaret illis secundum quod praeceptum est illi a Deo. PROPTER peccata, quae peccastis ante Deum, abducemini in Babyloniam captivi a Nabuchodonosor rege Babyloniorum.',
        2: 'Ingressi itaque in Babylonem, eritis ibi annis plurimis, et temporibus longis usque ad generationes septem: post hoc autem educam vos inde cum pace.',
        3: 'Nunc autem videbitis in Babylonia deos aureos, et argenteos, et lapideos, et ligneos in humeris portari, ostentantes metum Gentibus.',
        4: 'Videte ergo ne et vos similes efficiamini factis alienis, et metuatis, et metus vos capiat in ipsis.',
        5: 'Visa itaque turba de retro, et ab ante, adorantes, dicite in cordibus vestris: Te oportet adorari Domine.',
        6: 'Angelus enim meus vobiscum est: ipse autem exquiram animas vestras.',
        7: 'Nam ligna ipsorum polita a fabro, ipsa etiam inaurata, et inargentata falsa sunt, et non possunt loqui.',
        8: 'Et sicut virgini amanti ornamenta: ita accepto auro fabricati sunt.',
        9: 'Coronas certe aureas habent super capita sua dii illorum: unde subtrahunt sacerdotes ab eis aurum, et argentum, et erogant illud in semetipsos.',
        10: 'Dant autem et ex ipso prostitutis, et meretrices ornant: et iterum cum receperint illud a meretricibus, ornant deos suos.',
        11: 'Hi autem non liberantur ab aerugine, et tinea.',
        12: 'Opertis autem illis veste purpurea, extergunt faciem ipsorum propter pulverem domus, qui est plurimus inter eos.',
        13: 'Sceptrum autem habet ut homo, sicut iudex regionis, qui in se peccantem non interficit.',
        14: 'Habet etiam in manu gladium, et securim, se autem de bello, et a latronibus non liberat. Unde vobis notum sit quia non sunt dii.',
        15: 'Non ergo timueritis eos. Sicut enim vas hominis confractum inutile efficitur, tales sunt et dii illorum:',
        16: 'Constitutis illis in domo, oculi eorum pleni sunt pulvere a pedibus introeuntium.',
        17: 'Et sicut alicui, qui regem offendit, circumseptae sunt ianuae: aut sicut ad sepulchrum adductum mortuum, ita tutantur sacerdotes ostia clausuris, et seris, ne a latronibus expolientur.',
        18: 'Lucernas accendunt illis, et quidem multas, ex quibus nullam videre possunt: sunt autem sicut trabes in domo.',
        19: 'Corda vero eorum dicunt elingere serpentes, qui de terra sunt, dum comedunt eos, et vestimentum ipsorum, et non sentiunt.',
        20: 'Nigrae fiunt facies eorum a fumo, qui in domo fit.',
        21: 'Supra corpus eorum et supra caput eorum volant noctuae, et hirundines, et aves etiam similiter et cattae.',
        22: 'Unde sciatis quia non sunt dii. Ne ergo timueritis eos.',
        23: 'Aurum etiam, quod habent, ad speciem est. Nisi aliquis exterserit aeruginem, non fulgebunt: neque enim dum conflarentur, sentiebant.',
        24: 'Ex omni pretio empta sunt, in quibus spiritus non inest ipsis.',
        25: 'Sine pedibus in humeris portantur, ostentantes ignobilitatem suam hominibus. Confundantur etiam qui colunt ea.',
        26: 'Propterea si ceciderint in terram, a semetipsis non consurgunt: neque si quis eum statuerit rectum, per semetipsum stabit, sed sicut mortuis humeri eorum illis apponentur.',
        27: 'Hostias illorum vendunt Sacerdotes ipsorum, et abutuntur: similiter et mulieres eorum decerpentes, neque infirmo, neque mendicanti aliquid impertiunt,',
        28: 'de sacrificiis eorum foetae, et menstruatae contingunt. Sciens itaque ex his quia non sunt dii, ne timeatis eos.',
        29: 'Unde enim vocantur dii? Quia mulieres apponunt diis argenteis, et aureis, et ligneis:',
        30: 'et in domibus eorum sacerdotes sedent, habentes tunicas scissas, et capita, et barbam rasam, quorum capita nuda sunt.',
        31: 'Rugiunt autem clamantes contra deos suos, sicut in coena mortui.',
        32: 'Vestimenta eorum auferunt sacerdotes, et vestiunt uxores suas, et filios suos.',
        33: 'Neque siquid mali patiuntur ab aliquo, neque siquid boni, poterunt retribuere: neque regem constituere possunt, neque auferre.',
        34: 'Similiter neque dare divitias possunt, neque malum retribuere. Siquis illis votum voverit, et non reddiderit; neque hoc requirunt.',
        35: 'Hominem a morte non liberant, neque infirmum a potentiori eripiunt.',
        36: 'Hominem caecum ad visum non restituunt, de necessitate hominem non liberabunt.',
        37: 'Viduae non miserebuntur, neque orphanis benefacient.',
        38: 'Lapidibus de monte similes sunt dii illorum, lignei, et lapidei, et aurei, et argentei. Qui autem colunt ea, confundentur.',
        39: 'Quomodo ergo aestimandum est, aut dicendum, illos esse deos?',
        40: 'Adhuc enim ipsis Chaldaeis non honorantibus ea: qui cum audierint mutum non posse loqui, offerunt illud ad Bel, postulantes ab eo loqui:',
        41: 'quasi possint sentire qui non habent motum, et ipsi cum intellexerint, relinquent ea: sensum enim non habent ipsi dii illorum.',
        42: 'Mulieres autem circumdatae funibus in viis sedent, succendentes ossa olivarum.',
        43: 'Cum autem aliqua ex ipsis attracta ab aliquo transeunte dormierit cum eo, proximae suae exprobrat quod ea non sit digna habita, sicut ipsa, neque funis eius diruptus sit.',
        44: 'Omnia autem quae illi fiunt, falsa sunt. Quomodo aestimandum, aut dicendum est, illos esse deos?',
        45: 'A fabris autem, et ab aurificibus facta sunt. Nihil aliud erunt, nisi id quod volunt esse sacerdotes.',
        46: 'Aurifices etiam ipsi, qui ea faciunt, non sunt multi temporis. Numquid ergo possunt ea, quae fabricata sunt ab ipsis, esse dii?',
        47: 'Reliquerunt autem falsa, et opprobrium postea futuris.',
        48: 'Nam cum supervenerit illis praelium, et mala; cogitant sacerdotes apud se, ubi se abscondant cum illis.',
        49: 'Quomodo ergo sentiri debeant quoniam dii sunt, qui nec de bello se liberant, neque de malis se eripiunt?',
        50: 'Nam cum sint lignea, et lapidea inaurata, et inargentata, scietur postea quia falsa sunt ab universis Gentibus, et regibus: quae manifesta sunt quia non sunt dii, sed opera manuum hominum, et nullum Dei opus cum illis.',
        51: 'Unde ergo notum est, quia non sunt dii, sed opera manuum hominum, et nullum Dei opus in ipsis est?',
        52: 'Regem regioni non suscitant, neque pluviam hominibus dabunt.',
        53: 'Iudicium quoque non discernent, neque regiones liberabunt ab iniuria: quia nihil possunt, sicut corniculae inter medium caeli, et terrae.',
        54: 'Etenim cum inciderit ignis in domum deorum ligneorum, et lapideorum argenteorum, et aureorum, sacerdotes quidem ipsorum fugient, et liberabuntur: ipsi vero sicut trabes in medio comburentur.',
        55: 'Regi autem, et bello non resistent. Quomodo ergo aestimandum est, aut recipiendum quia dii sunt?',
        56: 'Non a furibus, neque a latronibus se liberabunt dii lignei, et lapidei, et inaurati, et inargentati, quibus iniqui fortiores sunt:',
        57: 'Aurum, et argentum, et vestimentum, quo operti sunt, auferent illis, et abibunt, nec sibi auxilium ferent.',
        58: 'Itaque melius est esse regem ostentantem virtutem suam: aut vas in domo utile, in quo gloriabitur qui possidet illud: vel ostium in domo, quod custodit quae in pace sunt, quam falsi dii.',
        59: 'Sol quidem, et luna, ac sidera cum sint splendida, et emissa ad utilitates, obaudiunt.',
        60: 'Similiter et fulgur cum apparuerit, perspicuum est: id ipsum autem et spiritus in omni regione spirat.',
        61: 'Et nubes, quibus cum imperatum fuerit a Deo perambulare in universum orbem, perficiunt quod imperatum est eis.',
        62: 'Ignis etiam missus desuper ut consumat montes, et silvas, facit quod praeceptum est ei. Haec autem neque speciebus, neque virtutibus uni eorum similia sunt.',
        63: 'Unde neque existimandum est, neque dicendum, illos esse deos, quando non possunt neque iudicium iudicare, neque quidquam facere hominibus.',
        64: 'Scientes itaque quia non sunt dii, ne ergo timueritis eos.',
        65: 'Neque enim regibus maledicent, neque benedicent.',
        66: 'Signa etiam in caelo Gentibus non ostendunt, neque ut sol lucebunt, neque illuminabunt ut luna.',
        67: 'Bestiae meliores sunt illis, quae possunt fugere sub tectum, ac prodesse sibi.',
        68: 'Nullo itaque modo nobis est manifestum quia sunt dii: propter quod ne timeatis eos.',
        69: 'Nam sicut in cucumerario formido nihil custodit: ita sunt dii illorum lignei, et argentei, et inaurati.',
        70: 'Eodem modo et in horto spina alba, supra quam omnis avis sedet. Similiter et mortuo proiecto in tenebris similes sunt dii illorum lignei, et inaurati, et inargentati:',
        71: 'A purpura quoque et murice, quae supra illos tenent, scietis itaque quia non sunt dii. Ipsi etiam postremo comeduntur, et erunt opprobrium in regione.',
        72: 'Melior est homo iustus, qui non habet simulacra: nam erit longe ab opprobriis.',
    },
}
